css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .88); position: relative; }
.loader span { position: absolute; background: linear-gradient(var(--accent-2), var(--accent)); clip-path: polygon(50% 0, 100% 100%, 0 100%); transform: scale(0); animation: sierp-grow calc(var(--loader-speed) * 3.4) cubic-bezier(.3, 1.4, .5, 1) infinite; }
.loader span:nth-of-type(1) { left: 25%; top: 0; width: 50%; height: 50%; }
.loader span:nth-of-type(2) { left: 0; top: 50%; width: 50%; height: 50%; animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-of-type(3) { left: 50%; top: 50%; width: 50%; height: 50%; animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-of-type(4) { left: 37.5%; top: 0; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed) * .44); }
.loader span:nth-of-type(5) { left: 25%; top: 25%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed) * .44); }
.loader span:nth-of-type(6) { left: 50%; top: 25%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed) * .44); }
.loader span:nth-of-type(7) { left: 12.5%; top: 50%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed) * .68); }
.loader span:nth-of-type(8) { left: 62.5%; top: 50%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed) * .68); }
.loader span:nth-of-type(9) { left: 37.5%; top: 75%; width: 25%; height: 25%; animation-delay: calc(var(--loader-speed) * .92); }
@keyframes sierp-grow { 0%, 4% { transform: scale(0); opacity: 0; } 20%, 72% { transform: scale(1); opacity: 1; } 90%, 100% { transform: scale(0); opacity: 0; } }
